const fs = require('fs');
const path = require('path');

// ============================================================
// generar_484_notas_y_fechas.js
// ============================================================
// Tres cosas que el chat no sabia y que si estan registradas.
//
// 1. LAS NOTAS DEL REGISTRO DIARIO
//    Son lo mas rico que hay —cuentan el contexto que ningun campo
//    estructurado captura— y el chat las tenia cargadas pero no las
//    mostraba:
//
//      Tú: ¿qué notas tengo?
//      Chiqui: Esto anotaste:
//              · 20 ago — "Comió pasto en el parque"
//              · 18 ago — "Durmió toda la tarde"
//
// 2. EL CUMPLEAÑOS
//      Tú: ¿cuándo es su cumpleaños?
//      Chiqui: Chiquito nació el 15 de marzo de 2019, así que tiene
//              7 años y 5 meses.
//              Faltan 203 días para su cumpleaños.
//
// 3. CUANDO LLEGO A CASA
//      Tú: ¿cuándo llegó a casa?
//      Chiqui: Chiquito llegó a tu casa el 30 de agosto de 2019.
//              Llevan 6 años y 11 meses juntos.
//              Su aniversario es en 6 días.
//
// El microchip ya funcionaba: esta en el perfil desde el script 473.
//
// REQUISITO: script 483 desplegado.
//
// Si algo no calza, ABORTA sin escribir NADA.
// ============================================================

const RUTA_CHAT = 'components/ChiquiChat.tsx';
const RUTA_FLOT = 'components/ChiquiFlotante.tsx';
const CHAT_B64 = '';
const FLOT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico NINGUN archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const dChat = path.join(process.cwd(), RUTA_CHAT);
const dFlot = path.join(process.cwd(), RUTA_FLOT);
for (const [r, d] of [[RUTA_CHAT, dChat], [RUTA_FLOT, dFlot]]) {
  if (!fs.existsSync(d)) abortar('no se encontro ' + r + '.');
}

const actual = fs.readFileSync(dChat, 'utf8');
if (actual.includes("case 'notas'")) {
  abortar('el chat ya tiene esto. Parece que este script ya se corrio.');
}
if (!actual.includes("case 'observaciones'")) {
  abortar('falta el script 475. Correlo primero.');
}

const chat = Buffer.from(CHAT_B64, 'base64').toString('utf8');
const flot = Buffer.from(FLOT_B64, 'base64').toString('utf8');

for (const r of ["case 'notas'", "case 'cumpleanos'", "case 'union'",
                 'function diasHastaCumple', 'function fechaLarga', 'Esto anotaste']) {
  if (!chat.includes(r)) abortar('el chat nuevo no incluye [' + r + ']. Script corrupto.');
}
console.log('  OK  los 3 temas nuevos estan');

for (const r of ['notas:', 'fechaUnion:', 'fecha_union']) {
  if (!flot.includes(r)) abortar('el flotante nuevo no incluye [' + r + ']. Script corrupto.');
}
console.log('  OK  el flotante trae las notas y la fecha de union');

fs.writeFileSync(dChat, chat, 'utf8');
console.log('');
console.log('OK: ' + RUTA_CHAT);
fs.writeFileSync(dFlot, flot, 'utf8');
console.log('OK: ' + RUTA_FLOT);
console.log('');
console.log('Prueba: "que notas tengo", "cuando es su cumpleaños" y');
console.log('"cuanto tiempo llevamos juntos".');
console.log('');
console.log('Listo.');
